-- Full-text search (FR-6.1), English configuration. Both vectors are generated by PostgreSQL, so
-- they can never be out of step with the text they come from; the JPA entities don't map them.
ALTER TABLE posts
	ADD COLUMN search_vector tsvector
	GENERATED ALWAYS AS (to_tsvector('english', search_text)) STORED;
CREATE INDEX posts_search_ix ON posts USING GIN (search_vector);

ALTER TABLE topics
	ADD COLUMN title_vector tsvector
	GENERATED ALWAYS AS (to_tsvector('english', title)) STORED;
CREATE INDEX topics_title_search_ix ON topics USING GIN (title_vector);
